"""
setup_project.py - Reaper Project File Generator
Run: python setup_project.py
Writes all project files for the Reaper token project.
"""
import os, base64

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
os.chdir(BASE_DIR)

files = {}

files["contracts/ReaperCoin.sol"] = ""

files["website/index.html"] = ""

files["scripts/deploy.js"] = ""

files["hardhat.config.js"] = ""

files["test/ReaperCoin.test.js"] = ""

files["package.json"] = ""

files["README.md"] = ""

for path, data in files.items():
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    with open(path, "wb") as f:
        f.write(base64.b64decode(data))
    print(f"Written: {path}")

print("\nAll files written successfully!")
